package com.smartcanteen.api; import com.smartcanteen.repo.OrderRepository; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController { final OrderRepository orders; AdminController(OrderRepository o){orders=o;} @GetMapping("/analytics") Map<String,Object> analytics(){var statuses=orders.countByStatus().stream().map(x->Map.of("status",x[0],"count",x[1])).toList();return Map.of("ordersToday",orders.count(),"statuses",statuses,"peakHours",List.of(Map.of("hour",11,"orders",12),Map.of("hour",13,"orders",28),Map.of("hour",17,"orders",24)));} }
